& \overrightarrow{\mathrm{r}}=\overrightarrow{\mathrm{a}}+\overrightarrow{\mathrm{b}}+\overrightarrow{\mathrm{c}}=4 \hat{\mathrm{i}}-\hat{\mathrm{j}}-3 \hat{\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}}=\hat{\mathrm{i}}+\hat{\mathrm{j}}-\hat{\mathrm{k}} \\
& \hat{\mathrm{r}}=\frac{\overrightarrow{\mathrm{r}}}{|\mathrm{r}|}=\frac{\hat{\mathrm{i}}+\hat{\mathrm{j}}-\hat{\mathrm{k}}}{\sqrt{1^2+1^2+(-1)^2}}=\frac{\hat{\mathrm{i}}+\hat{\mathrm{j}}-\hat{\mathrm{k}}}{\sqrt{3}}
\end{aligned}\)
